------------ LifeCycle ------------

function TrainFieldChooseAttributePopup:CleanField()
    self.listBtnSwitchElement = nil
    self.coClosePanel = nil
    self.indexSelected = nil
end

function TrainFieldChooseAttributePopup:Init()
    self:InitField()
    self:InitComponent()
end

function TrainFieldChooseAttributePopup:InitField()
    self.listBtnSwitchElement = {}
    self.datas = self.controller.Argument.parameters.datas
    for i, v in pairs(self.datas) do
        if v.id == checkNumber(self.controller.Argument.parameters.levelId) then
            self.indexSelected = i
            break
        end
    end
    --self.indexSelected = self.controller.Argument.parameters.selectIndex--UIBattleTrainFieldMgr.indexSelected
end



function TrainFieldChooseAttributePopup:InitComponent()
    local rootBtn = self.LayoutAttribute
    for i = 1, rootBtn.childCount do
        local childNode = rootBtn:GetChild(i - 1)
        local lbBtn = KTool.GetComponent(childNode.gameObject, typeof(LuaBehaviour))
        if not IsNull(lbBtn) then
            lbBtn:Init()
            local ltBtn = lbBtn.Env
            ltBtn:SetElementType(i) --设置 Node_ElementType
            ltBtn:SetCBClick(Bind(self, self.FunctionElementSelect))
            table.insert(self.listBtnSwitchElement, ltBtn)
        end
    end
    self:RefreshElementBtn()
end

function TrainFieldChooseAttributePopup:AddListener()
    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)

    SetButtonAction(self.BtnApply, function()
        --if checkNumber(UIBattleTrainFieldMgr.indexSelected) <= 0 then return end
        if self.coClosePanel then return end
        --if checkInt(UIBattleTrainFieldMgr.indexSelected) == checkInt(self.indexSelected) then return end
        --UIBattleTrainFieldMgr.indexSelected = self.indexSelected
        self.coClosePanel = cs_coroutine.start(function()
            SetButtonAction(self.BtnClose, nil)
            self:PlayPanelAnimation(ANIMA_PANEL_EXIT)
            self:ListNodesAnimationOnClose()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.8))
            Events.Broadcast(Constants.EventNames.ReSelectLevel, self.datas[self.indexSelected].id, self.datas)
            --UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self.datas[self.indexSelected].id, datas = self.datas}}, {
            --})
            UIModule.BackDialog()
            --UIBattlingCtrlMgr:GetInstance():ResetBattleWithChangeElement(UIBattleTrainFieldMgr.indexSelected)
            self.coClosePanel = nil
        end)
    end)
end

function TrainFieldChooseAttributePopup:RemoveListener()
end

function TrainFieldChooseAttributePopup:ListNodesAnimationOnClose()
    for i, btn in pairs(self.listBtnSwitchElement) do
        btn:PlayAnimationOnClose()
    end
end

function TrainFieldChooseAttributePopup:PlayPanelAnimation(name)
    if not IsNull(self.AnimaPanel) then
        self.AnimaPanel:Play(name)
    end
end

function TrainFieldChooseAttributePopup:FunctionElementSelect(index)
    self.indexSelected = index
    self:RefreshElementBtn(index)
end

function TrainFieldChooseAttributePopup:RefreshElementBtn()
    for i, btn in pairs(self.listBtnSwitchElement) do
        local elementType = btn.elementType
        btn:SetSelectedRootStatus(checkBool(elementType == self.indexSelected))
    end
    --if not isNull(self.ImgBlack) then
    --    KTool.SetActive(self.ImgBlack.gameObject, UIBattleTrainFieldMgr.indexSelected == self.indexSelected)
    --end
end

return TrainFieldChooseAttributePopup